create or replace function private.tool_traceability_current_role(p_workspace_id uuid) returns text language sql stable security definer set search_path=public,pg_temp as $$
 select m.role from public.tool_traceability_memberships m join public.workspace_members wm on wm.workspace_id=m.workspace_id and wm.user_id=m.user_id and wm.active=true join public.profiles p on p.id=m.user_id and p.status='active' where m.workspace_id=p_workspace_id and m.user_id=auth.uid() and m.enabled and m.status='active' limit 1;
$$;
create or replace function private.tool_traceability_capabilities(p_role text) returns jsonb language sql immutable as $$ select case p_role when 'ADMIN' then '["view","create_request","edit_request","approve","reject","return","extension_request","extension_review","manage_tools","manage_inventory","manage_personnel","comment","attach","audit","admin"]'::jsonb when 'LOGISTICS' then '["view","create_request","edit_request","approve","reject","return","extension_request","extension_review","manage_tools","manage_inventory","manage_personnel","comment","attach","audit"]'::jsonb when 'USER' then '["view","create_request","edit_own","extension_request","comment","attach"]'::jsonb else '["view"]'::jsonb end $$;
create or replace function private.tool_traceability_has_access(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select private.tool_traceability_current_role(p_workspace_id) is not null $$;
create or replace function private.tool_traceability_is_logistics(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce(private.tool_traceability_current_role(p_workspace_id) in('ADMIN','LOGISTICS'),false) $$;
create or replace function private.tool_traceability_is_admin(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select coalesce(private.tool_traceability_current_role(p_workspace_id)='ADMIN',false) $$;

create or replace function private.tool_traceability_profile_json(p_user uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p.id::text,'name',coalesce(p.display_name,p.email),'email',p.email,'photo',null,'photo_thumb',null) from public.profiles p where p.id=p_user;
$$;
create or replace function private.tool_traceability_tool_json(t public.tool_traceability_tools) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(t.payload,'{}'::jsonb)||jsonb_build_object('id',t.id,'name',t.name,'itemType',t.item_type,'category',t.category,'availability',t.availability,'assignedTo',t.assigned_to,'teamLeader',t.team_leader,'currentRequest',case when t.current_request_id is null then null else jsonb_build_object('linkedItems',jsonb_build_array(jsonb_build_object('id',t.current_request_id))) end,'stockQuantity',t.stock_quantity,'borrowedQuantity',t.borrowed_quantity,'createdAt',t.created_at,'updatedAt',t.updated_at,'version',t.version);
$$;
create or replace function private.tool_traceability_request_json(r public.tool_traceability_requests) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(r.payload,'{}'::jsonb)||jsonb_build_object('id',r.id,'name',r.name,'reference',r.reference,'requestStatus',r.request_status,'extensionState',r.extension_state,'borrowWindow',jsonb_build_object('from',r.borrow_from,'to',r.borrow_to),'actualReturn',r.actual_return,'teamMembers',r.team_members,'teamLeader',r.team_leader,'loggedBy',jsonb_build_array(private.tool_traceability_profile_json(r.creator_user_id)),'tools',jsonb_build_object('linkedItems',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name) order by t.name) from public.tool_traceability_request_tools rt join public.tool_traceability_tools t on t.workspace_id=rt.workspace_id and t.id=rt.tool_id where rt.workspace_id=r.workspace_id and rt.request_id=r.id),'[]'::jsonb)),'createdAt',r.created_at,'updatedAt',r.updated_at,'version',r.version);
$$;

create or replace function private.tool_traceability_recalc_inventory(p_workspace_id uuid,p_tool_id text) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$
declare qty bigint;
begin select coalesce(sum(rt.quantity),0) into qty from public.tool_traceability_request_tools rt join public.tool_traceability_requests r on r.workspace_id=rt.workspace_id and r.id=rt.request_id where rt.workspace_id=p_workspace_id and rt.tool_id=p_tool_id and rt.returned_at is null and r.archived_at is null and r.request_status in('Pending Approval','Borrowed'); update public.tool_traceability_tools set borrowed_quantity=qty,updated_at=now() where workspace_id=p_workspace_id and id=p_tool_id; end $$;

create or replace function public.tool_traceability_bootstrap(p_workspace_id uuid) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare caller uuid:=auth.uid(); role_name text; prof public.profiles%rowtype;
begin if caller is null then raise exception 'authentication required' using errcode='42501'; end if; if not exists(select 1 from public.workspace_members where workspace_id=p_workspace_id and user_id=caller and active=true) then raise exception 'workspace access denied' using errcode='42501'; end if; select * into prof from public.profiles where id=caller and status='active'; if not found then raise exception 'active profile required' using errcode='42501'; end if; select private.tool_traceability_current_role(p_workspace_id) into role_name; if role_name is null then role_name:=case when lower(coalesce(prof.platform_role,'')) in('admin','administrator','general manager','general_manager') then 'ADMIN' else 'USER' end; insert into public.tool_traceability_memberships(workspace_id,user_id,role,assigned_by) values(p_workspace_id,caller,role_name,null) on conflict do nothing; end if; return jsonb_build_object('role',role_name,'capabilities',private.tool_traceability_capabilities(role_name),'user',private.tool_traceability_profile_json(caller)); end $$;

create or replace function public.tool_traceability_list_tools(p_workspace_id uuid,p_search text default '',p_category text default null,p_availability text default null,p_limit int default 50,p_cursor text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare off int:=greatest(coalesce(nullif(p_cursor,'')::int,0),0); lim int:=least(greatest(coalesce(p_limit,50),1),200); total int; items jsonb;
begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select count(*) into total from public.tool_traceability_tools where workspace_id=p_workspace_id and archived_at is null and (coalesce(p_search,'')='' or name ilike '%'||p_search||'%') and (p_category is null or p_category='' or p_category='All' or category=p_category) and (p_availability is null or p_availability='' or p_availability='All' or availability=p_availability); select coalesce(jsonb_agg(private.tool_traceability_tool_json(x) order by x.name),'[]'::jsonb) into items from (select * from public.tool_traceability_tools where workspace_id=p_workspace_id and archived_at is null and (coalesce(p_search,'')='' or name ilike '%'||p_search||'%') and (p_category is null or p_category='' or p_category='All' or category=p_category) and (p_availability is null or p_availability='' or p_availability='All' or availability=p_availability) order by name limit lim offset off)x; return jsonb_build_object('items',items,'cursor',case when off+lim<total then (off+lim)::text else null end,'total',total); end $$;

create or replace function public.tool_traceability_list_requests(p_workspace_id uuid,p_search text default '',p_status text default null,p_extension_state text default null,p_limit int default 15,p_cursor text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare off int:=greatest(coalesce(nullif(p_cursor,'')::int,0),0);lim int:=least(greatest(coalesce(p_limit,15),1),200);total int;items jsonb;
begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select count(*) into total from public.tool_traceability_requests where workspace_id=p_workspace_id and archived_at is null and (coalesce(p_search,'')='' or name ilike '%'||p_search||'%' or reference ilike '%'||p_search||'%') and (p_status is null or p_status='' or p_status='All' or request_status=p_status) and (p_extension_state is null or p_extension_state='' or extension_state=p_extension_state); select coalesce(jsonb_agg(private.tool_traceability_request_json(x) order by x.created_at desc),'[]'::jsonb) into items from (select * from public.tool_traceability_requests where workspace_id=p_workspace_id and archived_at is null and (coalesce(p_search,'')='' or name ilike '%'||p_search||'%' or reference ilike '%'||p_search||'%') and (p_status is null or p_status='' or p_status='All' or request_status=p_status) and (p_extension_state is null or p_extension_state='' or extension_state=p_extension_state) order by created_at desc limit lim offset off)x; return jsonb_build_object('items',items,'cursor',case when off+lim<total then (off+lim)::text else null end,'total',total); end $$;

create or replace function public.tool_traceability_get_item(p_workspace_id uuid,p_board text,p_item_id text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare t public.tool_traceability_tools%rowtype;r public.tool_traceability_requests%rowtype; begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; if p_board='tools' then select * into t from public.tool_traceability_tools where workspace_id=p_workspace_id and id=p_item_id and archived_at is null;if not found then raise exception 'item not found' using errcode='P0002';end if;return private.tool_traceability_tool_json(t);else select * into r from public.tool_traceability_requests where workspace_id=p_workspace_id and id=p_item_id and archived_at is null;if not found then raise exception 'item not found' using errcode='P0002';end if;return private.tool_traceability_request_json(r);end if;end $$;

create or replace function public.tool_traceability_next_reference(p_workspace_id uuid) returns text language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v bigint; begin if not private.tool_traceability_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; insert into public.tool_traceability_reference_counters(workspace_id,value) values(p_workspace_id,0) on conflict do nothing; update public.tool_traceability_reference_counters set value=value+1,updated_at=now() where workspace_id=p_workspace_id returning value into v; return 'TRC-'||lpad(v::text,4,'0'); end $$;

create or replace function public.tool_traceability_create_tool(p_workspace_id uuid,p_fields jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare caller uuid:=auth.uid();t public.tool_traceability_tools%rowtype; begin if not private.tool_traceability_is_logistics(p_workspace_id) then raise exception 'tool management denied' using errcode='42501'; end if; insert into public.tool_traceability_tools(workspace_id,name,item_type,category,availability,payload,creator_user_id) values(p_workspace_id,left(trim(coalesce(p_fields->>'name','')),300),coalesce(nullif(p_fields->>'itemType',''),'Tool'),nullif(p_fields->>'category',''),coalesce(nullif(p_fields->>'availability',''),'Available'),p_fields-'name'-'itemType'-'category'-'availability',caller) returning * into t; return private.tool_traceability_tool_json(t); end $$;

create or replace function public.tool_traceability_update_tool(p_workspace_id uuid,p_tool_id text,p_updates jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare caller uuid:=auth.uid();t public.tool_traceability_tools%rowtype; begin if not private.tool_traceability_is_logistics(p_workspace_id) then raise exception 'tool management denied' using errcode='42501'; end if; select * into t from public.tool_traceability_tools where workspace_id=p_workspace_id and id=p_tool_id and archived_at is null for update;if not found then raise exception 'tool not found' using errcode='P0002';end if; update public.tool_traceability_tools set name=coalesce(nullif(p_updates->>'name',''),name),item_type=coalesce(nullif(p_updates->>'itemType',''),item_type),category=case when p_updates?'category' then p_updates->>'category' else category end,availability=coalesce(nullif(p_updates->>'availability',''),availability),assigned_to=case when p_updates?'assignedTo' then coalesce(p_updates->'assignedTo','[]'::jsonb) else assigned_to end,team_leader=case when p_updates?'teamLeader' then coalesce(p_updates->'teamLeader','[]'::jsonb) else team_leader end,current_request_id=case when p_updates?'currentRequest' then nullif(p_updates#>>'{currentRequest,linkedItems,0,id}','') else current_request_id end,payload=payload||(p_updates-'name'-'itemType'-'category'-'availability'-'assignedTo'-'teamLeader'-'currentRequest'),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_tool_id returning * into t; insert into public.tool_traceability_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type,detail) values(p_workspace_id,'tool',t.id,caller,'tool_updated',p_updates);return private.tool_traceability_tool_json(t); end $$;

create or replace function public.tool_traceability_archive_tool(p_workspace_id uuid,p_tool_id text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare caller uuid:=auth.uid();t public.tool_traceability_tools%rowtype; begin if not private.tool_traceability_is_logistics(p_workspace_id) then raise exception 'tool management denied' using errcode='42501'; end if; update public.tool_traceability_tools set archived_at=now(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_tool_id and archived_at is null returning * into t;if not found then raise exception 'tool not found' using errcode='P0002';end if;insert into public.tool_traceability_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type) values(p_workspace_id,'tool',t.id,caller,'tool_archived');return private.tool_traceability_tool_json(t);end $$;

create or replace function public.tool_traceability_create_request(p_workspace_id uuid,p_fields jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare caller uuid:=auth.uid();role_name text:=private.tool_traceability_current_role(p_workspace_id);r public.tool_traceability_requests%rowtype;ref text:=nullif(trim(coalesce(p_fields->>'reference','')),'');tool jsonb;tid text;qty int;
begin if role_name is null or role_name='VIEWER' then raise exception 'request creation denied' using errcode='42501';end if;if ref is null then ref:=public.tool_traceability_next_reference(p_workspace_id);end if;insert into public.tool_traceability_requests(workspace_id,reference,name,request_status,extension_state,borrow_from,borrow_to,team_members,team_leader,payload,creator_user_id) values(p_workspace_id,ref,left(trim(coalesce(p_fields->>'name',ref)),500),'Pending Approval','None',nullif(p_fields#>>'{borrowWindow,from}','')::date,nullif(p_fields#>>'{borrowWindow,to}','')::date,coalesce(p_fields->'teamMembers','[]'::jsonb),coalesce(p_fields->'teamLeader','[]'::jsonb),p_fields-'reference'-'name'-'requestStatus'-'extensionState'-'borrowWindow'-'teamMembers'-'teamLeader'-'tools'-'loggedBy'-'toolQuantities',caller) returning * into r;for tool in select * from jsonb_array_elements(coalesce(p_fields#>'{tools,linkedItems}','[]'::jsonb)) loop tid:=tool->>'id';qty:=greatest(coalesce((p_fields->'toolQuantities'->>tid)::int,1),1);if not exists(select 1 from public.tool_traceability_tools where workspace_id=p_workspace_id and id=tid and archived_at is null and availability='Available') then raise exception 'tool % is not available',tid using errcode='40001';end if;insert into public.tool_traceability_request_tools(workspace_id,request_id,tool_id,quantity) values(p_workspace_id,r.id,tid,qty) on conflict(workspace_id,request_id,tool_id) do update set quantity=excluded.quantity,returned_at=null;update public.tool_traceability_tools set availability='Pending Approval',assigned_to=jsonb_build_array(private.tool_traceability_profile_json(caller)),current_request_id=r.id,updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=tid;perform private.tool_traceability_recalc_inventory(p_workspace_id,tid);end loop;insert into public.tool_traceability_activity(workspace_id,entity_type,entity_id,actor_user_id,event_type,detail) values(p_workspace_id,'request',r.id,caller,'request_created',jsonb_build_object('reference',ref));return private.tool_traceability_request_json(r);end $$;;
